const fs = require('fs');
const path = 'admin-workstation.html';
let s = fs.readFileSync(path, 'utf8');

const oldVars = `    let currentToken = null;\n    let casesData = [];\n    let currentView = 'dashboard';\n    let currentQueueFilter = 'all';\n    let selectedCaseId = null;\n`;
const newVars = `    let currentToken = null;\n    let casesData = [];\n    let currentView = 'dashboard';\n    let currentQueueFilter = 'all';\n    let selectedCaseId = null;\n    let paymentPollTimer = null;\n    let paymentRenderTimer = null;\n`;
if (!s.includes(oldVars)) throw new Error('state variable block not found');
s = s.replace(oldVars, newVars);

const oldLogout = `    async function handleLogout() {\n      await db.auth.signOut();\n      currentToken = null;\n      selectedCaseId = null;\n      $('login').style.display = 'flex';\n    }\n`;
const newLogout = `    async function handleLogout() {\n      if (paymentPollTimer) clearTimeout(paymentPollTimer);\n      if (paymentRenderTimer) clearTimeout(paymentRenderTimer);\n      paymentPollTimer = null;\n      paymentRenderTimer = null;\n      await db.auth.signOut();\n      currentToken = null;\n      selectedCaseId = null;\n      $('login').style.display = 'flex';\n    }\n`;
if (!s.includes(oldLogout)) throw new Error('logout block not found');
s = s.replace(oldLogout, newLogout);

const oldFetchCases = `    async function fetchCases(show = false) {\n      try {\n        const res = await authFetch('/.netlify/functions/get_cases', { headers: headers() });\n        if (!res.ok) throw new Error('Could not load cases. Please log in again.');\n        casesData = await res.json();\n        if (!selectedCaseId && casesData.length) selectedCaseId = casesData[0].id;\n        render();\n        if (show) toast('Cases refreshed.');\n      } catch (e) {\n        $('main').innerHTML = '<div class=\"loader\">' + esc(e.message) + '</div>';\n      }\n    }\n`;
const newFetchCases = `    async function fetchCases(show = false) {\n      try {\n        const res = await authFetch('/.netlify/functions/get_cases', { headers: headers() });\n        if (!res.ok) throw new Error('Could not load cases. Please log in again.');\n        casesData = await res.json();\n        if (!selectedCaseId && casesData.length) selectedCaseId = casesData[0].id;\n        render();\n        schedulePaymentPolling();\n        if (show) toast('Cases refreshed.');\n      } catch (e) {\n        $('main').innerHTML = '<div class=\"loader\">' + esc(e.message) + '</div>';\n      }\n    }\n\n    function hasPendingPayments(list = casesData) {\n      return list.some(c => c.payment_status === 'pending' || c.status === 'payment_pending');\n    }\n\n    function userIsEditing() {\n      const active = document.activeElement;\n      return !!active && (active.matches?.('.fact-input, #letter-editor, input, textarea, select') || active.isContentEditable);\n    }\n\n    function renderPaymentUpdateWhenSafe(message) {\n      if (paymentRenderTimer) clearTimeout(paymentRenderTimer);\n      const attempt = () => {\n        if (!userIsEditing()) {\n          paymentRenderTimer = null;\n          render();\n          if (message) toast(message);\n          return;\n        }\n        paymentRenderTimer = setTimeout(attempt, 1200);\n      };\n      attempt();\n    }\n\n    function schedulePaymentPolling(delayMs = 8000) {\n      if (paymentPollTimer) clearTimeout(paymentPollTimer);\n      paymentPollTimer = null;\n      if (!currentToken || !hasPendingPayments()) return;\n      paymentPollTimer = setTimeout(pollPendingPayments, delayMs);\n    }\n\n    async function pollPendingPayments() {\n      paymentPollTimer = null;\n      if (!currentToken || !hasPendingPayments()) return;\n\n      const pendingBefore = new Set(\n        casesData\n          .filter(c => c.payment_status === 'pending' || c.status === 'payment_pending')\n          .map(c => c.id)\n      );\n\n      try {\n        const res = await authFetch('/.netlify/functions/get_cases', { headers: headers() });\n        if (!res.ok) throw new Error('Could not refresh payment status.');\n        const freshCases = await res.json();\n        const newlyPaid = freshCases.filter(c =>\n          pendingBefore.has(c.id) &&\n          c.payment_status === 'paid' &&\n          c.status === 'paid_ready_for_drafting'\n        );\n\n        if (newlyPaid.length) {\n          casesData = freshCases;\n          const names = newlyPaid.map(c => facts(c).client_name || c.client_name || 'Client');\n          const message = newlyPaid.length === 1\n            ? 'Payment confirmed for ' + names[0] + '. The case is ready for drafting.'\n            : newlyPaid.length + ' payments were confirmed. Those cases are ready for drafting.';\n          renderPaymentUpdateWhenSafe(message);\n        }\n\n        if (hasPendingPayments(freshCases)) schedulePaymentPolling();\n      } catch (e) {\n        if (currentToken) schedulePaymentPolling(15000);\n      }\n    }\n`;
if (!s.includes(oldFetchCases)) throw new Error('fetchCases block not found');
s = s.replace(oldFetchCases, newFetchCases);

fs.writeFileSync(path, s);
console.log('Added targeted payment-state polling.');
